import{_ as n,o as t,c as r,a2 as i}from"./chunks/framework.Buc7gXeZ.js";const g=JSON.parse('{"title":"Externe Links im Überblick","description":"Alle nach außen offenen Zugänge eines Space an einer Stelle prüfen.","frontmatter":{"title":"Externe Links im Überblick","description":"Alle nach außen offenen Zugänge eines Space an einer Stelle prüfen."},"headers":[],"relativePath":"zusammenarbeit/externe-links.md","filePath":"zusammenarbeit/externe-links.md","lastUpdated":1786092153000}'),a={name:"zusammenarbeit/externe-links.md"};function s(l,e,d,o,h,c){return t(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="externe-links-im-uberblick" tabindex="-1">Externe Links im Überblick <a class="header-anchor" href="#externe-links-im-uberblick" aria-label="Permalink to &quot;Externe Links im Überblick&quot;">​</a></h1><p>Unter <strong>Space Einstellungen → Links</strong> stehen alle externen Zugänge eines Space:</p><blockquote><p><em>Hier ist eine Liste aller externen Links in diesem Space</em></p></blockquote><div class="tip custom-block"><p class="custom-block-title">Die wichtigste Seite für den Überblick</p><p>Dies ist die <strong>einzige</strong> Stelle, an der alle nach außen offenen Zugänge gesammelt sichtbar sind. Formularlinks entstehen im Formular, Portallinks auf der Seite, Webhook-Adressen im Flow — hier laufen sie zusammen.</p><p>Wer wissen will, was von außen erreichbar ist, sieht hier nach.</p></div><h2 id="link-typen" tabindex="-1">Link-Typen <a class="header-anchor" href="#link-typen" aria-label="Permalink to &quot;Link-Typen&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Typ</th><th>Bedeutung</th><th>Entsteht in</th></tr></thead><tbody><tr><td><strong>Eintrag hinzufügen</strong></td><td>Formularlink zum Anlegen</td><td><a href="/docs/formulare/formular-teilen">Formular teilen</a></td></tr><tr><td><strong>Eintrag bearbeiten</strong></td><td>Formularlink zum Bearbeiten</td><td><a href="/docs/formulare/eintraege-bearbeiten">Einträge per Formular bearbeiten</a></td></tr><tr><td><strong>Seite</strong></td><td>Portal-Link</td><td><a href="/docs/seiten/portal-veroeffentlichen">Portal veröffentlichen</a></td></tr><tr><td><strong>Flow starten</strong></td><td>Webhook-Adresse</td><td><a href="/docs/flows/webhook-trigger">Flow per Webhook starten</a></td></tr><tr><td><strong>Flow Ausführung</strong></td><td>Link auf einen laufenden Durchlauf</td><td><a href="/docs/flows/seiten-in-flows">Seiten in Flows</a></td></tr><tr><td><strong>Space-Einladung</strong></td><td>Einladungslink</td><td><a href="/docs/zusammenarbeit/personen-einladen">Personen einladen</a></td></tr></tbody></table><p>Links ohne Namen erscheinen als <strong>Unbenannt</strong>.</p><div class="tip custom-block"><p class="custom-block-title">Links benennen</p><p>Wenn Sie über <em>Link hinzufügen</em> mehrere Links auf dasselbe Formular anlegen, vergeben Sie sprechende Namen — „Newsletter&quot;, „Messestand&quot;, „Website&quot;. Sonst stehen hier fünf Einträge, bei denen niemand mehr weiß, welcher wozu gehört.</p></div><h2 id="warum-das-regelmaßig-prufen" tabindex="-1">Warum das regelmäßig prüfen <a class="header-anchor" href="#warum-das-regelmaßig-prufen" aria-label="Permalink to &quot;Warum das regelmäßig prüfen&quot;">​</a></h2><div class="danger custom-block"><p class="custom-block-title">Ein Link bleibt aktiv, bis er entfernt wird</p><p>Geteilte Links laufen nicht ab. Sie funktionieren weiter:</p><ul><li>nachdem das Projekt beendet ist</li><li>nachdem die Kampagne ausgelaufen ist</li><li>nachdem die Person das Unternehmen verlassen hat</li><li>nachdem der anbindende Dienst abgeschaltet wurde</li></ul><p>Niemand wird Sie darauf hinweisen. Nur diese Liste zeigt, was noch offen ist.</p></div><p>Ein sinnvoller Anlass für eine Durchsicht:</p><table tabindex="0"><thead><tr><th>Anlass</th><th>Worauf achten</th></tr></thead><tbody><tr><td><strong>Projekt abgeschlossen</strong></td><td>Portale und Formulare des Projekts</td></tr><tr><td><strong>Kampagne beendet</strong></td><td>Die zugehörigen benannten Formularlinks</td></tr><tr><td><strong>Personalwechsel</strong></td><td>Alles, was diese Person erstellt oder erhalten hat</td></tr><tr><td><strong>Fremdsystem abgeschaltet</strong></td><td>Webhook-Adressen vom Typ <em>Flow starten</em></td></tr><tr><td><strong>Regelmäßig, etwa quartalsweise</strong></td><td>Alles</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">Nach einem Personalwechsel besonders wichtig</p><p>Das Entfernen einer Person aus dem Space beendet nur ihren <strong>Space-Zugriff</strong>. Links, die sie erstellt oder erhalten hat, funktionieren weiter — auch für sie.</p><p>→ <a href="/docs/zusammenarbeit/personen-einladen">Personen einladen</a></p></div><h2 id="link-entfernen" tabindex="-1">Link entfernen <a class="header-anchor" href="#link-entfernen" aria-label="Permalink to &quot;Link entfernen&quot;">​</a></h2><p>Über die Liste. Ein entfernter Link funktioniert <strong>sofort</strong> nicht mehr — auch nicht für Personen, die ihn gespeichert haben oder ihn gerade geöffnet halten.</p><div class="danger custom-block"><p class="custom-block-title">Gedruckte Codes und eingebettete Portale</p><p>Ein QR-Code auf einem Aushang oder ein in eine fremde Website eingebettetes Portal lässt sich nicht zurückrufen. Beides zeigt nach dem Entfernen ins Leere.</p><p>Prüfen Sie vor dem Löschen, wo ein Link im Umlauf ist. Für gedrucktes Material lohnt sich ein eigener, dauerhaft bestehender Link.</p></div><p>Bereits eingegangene Einträge bleiben selbstverständlich erhalten.</p><h2 id="zugriff-beschranken-statt-entfernen" tabindex="-1">Zugriff beschränken statt entfernen <a class="header-anchor" href="#zugriff-beschranken-statt-entfernen" aria-label="Permalink to &quot;Zugriff beschränken statt entfernen&quot;">​</a></h2><p>Statt einen Link zu löschen, können Sie ihn beschränken:</p><table tabindex="0"><thead><tr><th>Was Sie teilen</th><th>Möglichkeiten</th></tr></thead><tbody><tr><td><strong>Formular</strong></td><td><em>Jeder</em> / <em>Jeder registrierte Benutzer</em> / <em>Jeder aus diesem Space</em></td></tr><tr><td><strong>Ansicht oder Portal</strong></td><td><em>Alle</em> / <em>Mit Anmeldeinformationen</em></td></tr></tbody></table><p>→ <a href="/docs/zusammenarbeit/zugriff-beschraenken">Zugriff auf geteilte Inhalte</a></p><h2 id="was-die-liste-nicht-zeigt" tabindex="-1">Was die Liste nicht zeigt <a class="header-anchor" href="#was-die-liste-nicht-zeigt" aria-label="Permalink to &quot;Was die Liste nicht zeigt&quot;">​</a></h2><div class="warning custom-block"><p class="custom-block-title">Zwei Einschränkungen</p><ul><li><strong>Sie ist auf einen Space begrenzt.</strong> Bei mehreren Spaces müssen Sie jeden einzeln prüfen.</li><li><strong>Die Anzeige kann gefiltert sein.</strong> Je nach Einstellung sind nicht alle technischen Linktypen sichtbar. Für eine vollständige Bestandsaufnahme sensibler Zugänge sollten Sie zusätzlich die Freigabedialoge der einzelnen Formulare, Ansichten und Seiten durchsehen.</li></ul></div><h2 id="anzahl-der-links" tabindex="-1">Anzahl der Links <a class="header-anchor" href="#anzahl-der-links" aria-label="Permalink to &quot;Anzahl der Links&quot;">​</a></h2><div class="warning custom-block"><p class="custom-block-title">Tarifabhängig</p><p>Wie viele zusätzliche Links Sie je Formular oder Portal anlegen können, hängt vom Tarif ab.</p></div><h2 id="weiter" tabindex="-1">Weiter <a class="header-anchor" href="#weiter" aria-label="Permalink to &quot;Weiter&quot;">​</a></h2><ul><li><a href="/docs/zusammenarbeit/zugriff-beschraenken">Zugriff auf geteilte Inhalte</a></li><li><a href="/docs/spaces/einstellungen">Space-Einstellungen</a></li><li><a href="/docs/zusammenarbeit/personen-einladen">Personen einladen</a></li></ul>',27)])])}const m=n(a,[["render",s]]);export{g as __pageData,m as default};
